sizes = [1.0, 1.5, 2.0, 2.5, 3.0]
prices = [2.0, 2.8, 3.7, 4.1, 5.2]
def mse_of(w, b):
    r = [(w * x + b) - y for x, y in zip(sizes, prices)]
    return sum(e * e for e in r) / len(r)

scores = {'A': mse_of(1.5, 0.5), 'B': mse_of(1.0, 1.0)}
print(min(scores, key=scores.get), {k: round(v, 3) for k, v in scores.items()})
